/* TAREA 1 7-SEGMENTOS 
 * Hecho por: Juliana Andrea Vasquez Quintero 
 * CONEXIONES A CADA PIN EN EL MICROCONTROLADOR
 *
 * Para el 7-segmentos:
 *  -Pin 1 del 7-segmentos, conectado a PC10 del micro-controlador, Segmento E.
 *	-Pin 2 del 7-segmentos, conectado a PC12 del micro-controlador, Segmento D.
 *	-Pin 4 del 7-segmentos, conectado a PC11 del micro-controlador, Segmento C.
 *	-Pin 5 del 7-segmentos, conectado a PD2 del micro-controlador, Segmento G.
 *	-Pin 7 del 7-segmentos, conectado a PA12 del micro-controlador, Segmento B.
 *	-Pin 10 del 7-segmentos, conectado a PA11 del micro-controlador, Segmento F.
 *	-Pin 11 del 7-segmentos, conectado a PB12 del micro-controlador, Segmento A.
 *
 *  Anodo comun:
 *  -Pin 6 del 7-segmentos, conectado al colector de un transistor, lo nombraremos T6.
 *	-Pin 8 del 7-segmentos, conectado al colector de un transistor, lo nombraremos T8.
 *	-Pin 9 del 7-segmentos, conectado al colector de un transistor, lo nombraremos T9.
 *	-Pin 12 del 7-segmentos, conectado al colector de un transistor, lo nombraremos T12.
 *
 * Para los 4 transistores:
 *
 *	-La base de T6 conectada a PC13.
 *	-La base de T8 conectada a PC6.
 *	-La base de T9 conectada a PC5.
 *	-La base de T12 conectada a PB7.
 *
 * Para las dos fotointerruptor:
 *
 *	-El colector del foto-transistor que suma y detecta flanco de subida está conectado a PC3.
 *	-El colector del foto-transistor que resta y detecta flanco de bajada está conectado a PA1.
 *
 *	El resto de conexiones son a tierra o a la alimentación, la cual es 3.3V.
 **************************************************************************************************
 * @hardware_description
 * 
 * 1. Microcontrolador / Tarjeta de desarrollo:
 *    - STM32F411RE (ARM Cortex-M4 @ 84 MHz) / Tarjeta NUCLEO-F411RE.
 * 
 * 2. Fotointerruptores (Sensores Optoacopladores / Encoders ópticos):
 *    - Fotointerruptor 1 (Incremente +1):
 *      * Configuración: Interrupción externa (EXTI) por flanco de subida (RISING).
 *    - Fotointerruptor 2 (Decremente -1):
 *      * Configuración: Interrupción externa (EXTI) por flanco de bajada (FALLING).
 * 
 * 3. Display de 7 Segmentos (4 dígitos, Multiplexado):
 *    - Tipo: Ánodo común.
 * 
 * 4. Indicador de Estado (LED Blinky):
 *    - LED integrado en placa (LED2)
 * 
 * @peripherals_used
 * - TIM3: Timer configurado para el refresco de pantalla multiplexada .
 * - TIM2: Timer configurado para la conmutación periódica del LED de estado (Blinky).
 * - EXTI: Líneas de interrupción externa para la lectura síncrona de los fotointerruptores.
 * - GPIO: Puertos de salida digital para segmentos, dígitos y LED.
 *
 */


#include "stm32f411xe.h"
#include <stm32f4xx.h>
#include <stdint.h>

//Definicion de variables 

volatile uint8_t flag_sumar = 0; //para foto-transistor que suma
volatile uint8_t flag_restar = 0; //para foto-transistor que resta
volatile int32_t contador = 0; //Contador interrupciones de los fotointerruptores
volatile uint8_t digito_actual = 0;//digito del 7-segemento
volatile uint8_t mostrar = 0;



//Cabecera de funciones 
void init_GPIO(void);
void init_timer2(void);//para el parpadeo del LED2
void init_timer3(void);//para el 7-segmentos
void init_EXTI(void);
void Mostrar_Segmentos(uint8_t numero);
void Actualizar_Contador(void);



//Main
int main(void)
{
    init_GPIO();
    init_timer2();
    init_timer3();
    init_EXTI();



    /* Loop forever */
	while (1) {
        //Procesar la actualización del contador
        Actualizar_Contador();
        if (mostrar == 1) {
            mostrar = 0;

            //Apagamos todos los transistores 
           /*---Puerto B, T12(PB7) ---*/
            GPIOB->BSRR = GPIO_BSRR_BS7; //Ponemos 0 logico ya que usamos transistores PNP

           /*---Puerto C, T6(PC13), T8(PC6), T9(PC5) ---*/
            GPIOC->BSRR = (GPIO_BSRR_BS13 | GPIO_BSRR_BS6 | GPIO_BSRR_BS5); //Ponemos 0 logico ya que usamos transistores PNP

           // Extraemos cada dígito del contador actual
            uint8_t d1 = (contador / 1000) % 10; // Miles (Dígito 1 - Izquierda)
            uint8_t d2 = (contador / 100) % 10;  // Centenas (Dígito 2)
            uint8_t d3 = (contador / 10) % 10;   // Decenas (Dígito 3)
            uint8_t d4 = contador % 10;          // Unidades (Dígito 4 - Derecha)

            //Encendemoos el segmento correspondiente 
          switch (digito_actual) {
            case 0:
                Mostrar_Segmentos(d1); // Mostramos los miles
                GPIOB->BSRR = GPIO_BSRR_BR7; // Encender T12 (PB7) -> Pin 12 -> DIG.1 (Izquierda)
                break;
            case 1:
                Mostrar_Segmentos(d2); // Mostramos las centenas
                GPIOC->BSRR = GPIO_BSRR_BR5; // Encender T9 (PC5) -> Pin 9 -> DIG.2
                break;
            case 2:
                Mostrar_Segmentos(d3); // Mostramos las decenas
                GPIOC->BSRR = GPIO_BSRR_BR6; // Encender T8 (PC6) -> Pin 8 -> DIG.3
                break;
            case 3:
                Mostrar_Segmentos(d4); // Mostramos las unidades
                GPIOC->BSRR = GPIO_BSRR_BR13; // Encender T6 (PC13) -> Pin 6 -> DIG.4 (Derecha)
                break;
        }
        //Preparar el siguiente dígito para la próxima interrupción
        digito_actual++;
        if (digito_actual > 3) {
            digito_actual = 0;
        }
    }
    

        }

    return 0;
    
}


//Definicion de funciones 

/*----- GPIO-----*/
void init_GPIO(void){
    // Activamos la señal de reloj para los puertos A,B,C,D y H
    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOBEN | RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIODEN| RCC_AHB1ENR_GPIOHEN); 
    RCC->AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOBEN | RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIODEN| RCC_AHB1ENR_GPIOHEN);


    // Configuracion de los pines del 7-segmento como salida para el control de los leds 

    /*---Puerto A, B(PA12), F(PA11) ---*/
    GPIOA->MODER &= ~(GPIO_MODER_MODE12 | GPIO_MODER_MODE11); //Limpiamos para el pin PA12 y PA11
    GPIOA->MODER |= (GPIO_MODER_MODE12_0 | GPIO_MODER_MODE11_0); //Configuramos como salipa los pines PA12 y PA11

    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT12 | GPIO_OTYPER_OT11); //Configuramos como salida push-pull

    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED12 | GPIO_OSPEEDR_OSPEED11); //Configuramos los pines como baja velocidad 

    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD12 | GPIO_PUPDR_PUPD11); //Cnfigurar los pines sin pull-up y pull-down

    /*---Puerto B, A(PB12) ---*/
    GPIOB->MODER &= ~(GPIO_MODER_MODE12); //Limpiamos para el pin PB12
    GPIOB->MODER |= (GPIO_MODER_MODE12_0); //Configuramos como salipa el pin PB12 

    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT12); //Configuramos como salida push-pull

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED12); //Configuramos el pin como baja velocidad 

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD12); //Cnfigurar el pin sin pull-up y pull-down

    /*---Puerto C, E(PC10), D(PC12), C(PC11) ---*/
    GPIOC->MODER &= ~(GPIO_MODER_MODE12 | GPIO_MODER_MODE11 | GPIO_MODER_MODE10); //Limpiamos para el pin PC12, PC10 y PC11
    GPIOC->MODER |= (GPIO_MODER_MODE12_0 | GPIO_MODER_MODE11_0 | GPIO_MODER_MODE10_0); //Configuramos como salipa los pines PC12, PC10 y PC11

    GPIOC->OTYPER &= ~(GPIO_OTYPER_OT12 | GPIO_OTYPER_OT11 | GPIO_OTYPER_OT10); //Configuramos como salida push-pull

    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED12 | GPIO_OSPEEDR_OSPEED11 | GPIO_OSPEEDR_OSPEED10); //Configuramos los pines como baja velocidad 

    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD12 | GPIO_PUPDR_PUPD11 | GPIO_PUPDR_PUPD10); //Cnfigurar los pines sin pull-up y pull-down

    /*---Puerto D, G(PD2) ---*/
    GPIOD->MODER &= ~(GPIO_MODER_MODE2); //Limpiamos para el pin PD2
    GPIOD->MODER |= (GPIO_MODER_MODE2_0); //Configuramos como salipa el pin PD2 

    GPIOD->OTYPER &= ~(GPIO_OTYPER_OT2); //Configuramos como salida push-pull

    GPIOD->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED2); //Configuramos el pin como baja velocidad 

    GPIOD->PUPDR &= ~(GPIO_PUPDR_PUPD2); //Cnfigurar el pin sin pull-up y pull-down


    //Configuracion de los pines conectados a la base de los transistores, como salida, para el control de los anodos comunes de los leds 

    /*---Puerto B, T12(PB7) ---*/
    GPIOB->MODER &= ~(GPIO_MODER_MODE7); //Limpiamos para el pin PB7
    GPIOB->MODER |= (GPIO_MODER_MODE7_0); //Configuramos como salipa el pin PB7 

    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT7); //Configuramos como salida push-pull

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED7); //Configuramos el pin como baja velocidad 

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD7); //Cnfigurar el pin sin pull-up y pull-down

    /*---Puerto C, T6(PC13), T8(PC6), T9(PC5) ---*/
    GPIOC->MODER &= ~(GPIO_MODER_MODE13 | GPIO_MODER_MODE6 | GPIO_MODER_MODE5); //Limpiamos para el pin PC13, PC6 y PC5
    GPIOC->MODER |= (GPIO_MODER_MODE13_0 | GPIO_MODER_MODE6_0 | GPIO_MODER_MODE5_0); //Configuramos como salipa los pines PC13, PC6 y PC5

    GPIOC->OTYPER &= ~(GPIO_OTYPER_OT13 | GPIO_OTYPER_OT6 | GPIO_OTYPER_OT5); //Configuramos como salida push-pull

    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED13 | GPIO_OSPEEDR_OSPEED6 | GPIO_OSPEEDR_OSPEED5); //Configuramos los pines como baja velocidad 

    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD13 | GPIO_PUPDR_PUPD6 | GPIO_PUPDR_PUPD5); //Cnfigurar los pines sin pull-up y pull-down


    //Configuracion del pin PH1 como salida, para encender el led2 asociado a la placa auxiliar para indicar que el programa funciona 
    GPIOH->MODER &= ~(GPIO_MODER_MODE1); //Limpiamos para el pin PH1
    GPIOH->MODER |= (GPIO_MODER_MODE1_0); //Configuramos como salipa el pin PH1 

    GPIOH->OTYPER &= ~(GPIO_OTYPER_OT1); //Configuramos como salida push-pull

    GPIOH->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED1); //Configuramos el pin como baja velocidad 

    GPIOH->PUPDR &= ~(GPIO_PUPDR_PUPD1); //Configurar el pin sin pull-up y pull-down


    //Poner en 0 el led2 para encenderlo 
    GPIOH->BSRR = GPIO_BSRR_BS1; //Encender el led2 de la placa auxiliar


    //Configuracion de las foto compuertas como entrada 

    /*---Puerto A, restador (PA1) ---*/
    GPIOA->MODER &= ~(GPIO_MODER_MODE1);

    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD1);//Configurar el pin sin pull-up y pull-down


    /*---Puerto C, sumador (PC3) ---*/
    GPIOC->MODER &= ~(GPIO_MODER_MODE3);

    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD3);//Configurar el pin sin pull-up y pull-down


}


/*---EXTI---*/
void init_EXTI(void){
    //Activamos la señal de reloj para el SYSCF
    RCC->APB2ENR &= ~(RCC_APB2ENR_SYSCFGEN);
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;


    //Enlazamos el puerto PA1 en la linea EXTI1 y PC3 a EXTI3
    SYSCFG->EXTICR[0] &= ~(SYSCFG_EXTICR1_EXTI1 | SYSCFG_EXTICR1_EXTI3);//Limpiamos la seleccion del puerto para la linea 1 
    SYSCFG->EXTICR[0] |= (SYSCFG_EXTICR1_EXTI1_PA | SYSCFG_EXTICR1_EXTI3_PC); //Seleccionamos el puerto del cual viene la linea



    //Configuramos los flancos (Subida para PC3 y bajada para PA1 )

    /*---PC3---*/
    EXTI->RTSR |= EXTI_RTSR_TR3; // Habilitamos el flanco de subida para la linea 3 
    EXTI->FTSR &= ~(EXTI_FTSR_TR3); //Deshabilitamos el flanco de bajada para la linea 3

    /*---PA1---*/
    EXTI->FTSR |= EXTI_FTSR_TR1; //Habilitamos el flanco de bajada para la linea 1 
    EXTI->RTSR &= ~(EXTI_RTSR_TR1); //Deshabilitamos el flanco de subida para la linea 1 

    //Generacon de una solicitud de interrupcion 
    EXTI->SWIER &= ~(EXTI_SWIER_SWIER1 | EXTI_SWIER_SWIER3);

    //Desenmascarar las interrupciones 
    EXTI->IMR |= (EXTI_IMR_IM1 | EXTI_IMR_IM3); //Le quitamos la mascara 

    //Activacion en el NVIC
    NVIC_EnableIRQ(EXTI1_IRQn);
    NVIC_EnableIRQ(EXTI3_IRQn);

}

/*---Rutina de servicio de interrupcion (ISR) para el flanco de subida PC3---*/
void EXTI3_IRQHandler(void){
    if (EXTI->PR & EXTI_PR_PR3) {
        EXTI->PR = EXTI_PR_PR3; // Limpiar la bandera de hardware escribiendo un 1
        flag_sumar = 1; // Levantamos la bandera de software para el main
    }
}

/*---Rutina de servicio de interrupcion (ISR) para el flanco de bajada PA1---*/
void EXTI1_IRQHandler(void) {
    if (EXTI->PR & EXTI_PR_PR1) {
        EXTI->PR = EXTI_PR_PR1; // Limpiar la bandera de hardware escribiendo un 1
        flag_restar = 1; // Levantamos la bandera de software para el main
    }
}


/*---TIMER2para el parpadeo del LED2---*/
void init_timer2(void){
    //Activamos la señal de reloj para el TIM2 
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM2EN);
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;

    //Configuramos el PSC y el ARR para 500ms 
    TIM2->CNT = 0; //Reiniciamos el contador en 0
    TIM2->PSC = (16000-1);
    TIM2->ARR = (500-1); //Cuenta 500ms (de 0 a 499)

    TIM2->CR1 &= ~(0x3 << TIM_CR1_CKD_Pos); //Limpiamos, dejar la señal de reloj completa
    TIM2->CR1 &= ~(TIM_CR1_ARPE); //Limiando la posicion 
    TIM2->CR1 |= (TIM_CR1_ARPE); //Activando el preload para el ARR
    TIM2->CR1 &= ~TIM_CR1_DIR; //Limpiando, contador de forma ascendente

    TIM2->DIER |= TIM_DIER_UIE; // Activamos la interrupcion  debida a un evento aqui


    //Configuramos el NVIC
    __NVIC_EnableIRQ(TIM2_IRQn); //Activamos la interrupcion del NVIC

    TIM2->CR1 |= TIM_CR1_CEN; //Activamos el contador 

}

/*---Rutina de servicio de interrupcion (ISR) para el TIM2---*/
void TIM2_IRQHandler (void){

    //Operacion logica de toda la variable y verificando si la bandera esta levantada 
    if (TIM2->SR & TIM_SR_UIF) {
        TIM2->SR &= ~TIM_SR_UIF; //Limpiando la bandera 

        GPIOH->ODR ^=GPIO_ODR_ODR_1; //Alterar el estado del PH1 
    
    }

}


/*---TIMER3 para el 7-segmentos---*/
void init_timer3 (void){
    //Activamos la señal de reloj para el TIM3
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM3EN);
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;

    //Configurar PSC y ARR para 2 ms (Reloj base = 16 MHz)
    TIM3->CNT = 0; //Reiniciando el contador 

    TIM3->PSC = (16000 - 1); // 1ms por conteo 
    TIM3->ARR = (5 - 1); // Para generar un evento update cada 5ms

    TIM3->CR1 &= ~(0x3 << TIM_CR1_CKD_Pos); //Limpiamos, dejar la señal de reloj completa
    TIM3->CR1 &= ~(TIM_CR1_ARPE); //Limiando la posicion 
    TIM3->CR1 |= (TIM_CR1_ARPE); //Activando el preload para el ARR
    TIM3->CR1 &= ~TIM_CR1_DIR; //Limpiando, contador de forma ascendente

    TIM3->DIER |= TIM_DIER_UIE; // Activamos la interrupcion  debida a un evento aqui


    //Configuramos el NVIC
    __NVIC_EnableIRQ(TIM3_IRQn); //Activamos la interrupcion del NVIC

    TIM3->CR1 |= TIM_CR1_CEN; //Activamos el contador 

}

/*---Rutina de servicio de interrupcion (ISR) para el TIM3---*/
void TIM3_IRQHandler(void){
    if (TIM3->SR & TIM_SR_UIF) {
        TIM3->SR &= ~TIM_SR_UIF; // Limpiar la bandera del temporizador
        mostrar = 1;

    }
}


// Con la siguiente función, encendemos el segmento de tal manera que aparezca el número correspondiente en pantalla.
void Mostrar_Segmentos(uint8_t numero){
    //Primero, apagamos TODOS los segmentos
    /*---Puerto A, B(PA12), F(PA11) ---*/
    GPIOA->BSRR = (GPIO_BSRR_BS12 | GPIO_BSRR_BS11); //Ponemos 1 logico para asegurar que inicien apagados

    /*---Puerto B, A(PB12) ---*/
    GPIOB->BSRR = GPIO_BSRR_BS12;//Ponemos 1 logico para asegurar que inicien apagados

    /*---Puerto C, E(PC10), D(PC12), C(PC11) ---*/
    GPIOC->BSRR = (GPIO_BSRR_BS11 | GPIO_BSRR_BS10 | GPIO_BSRR_BS12);//Ponemos 1 logico para asegurar que inicien apagados

    /*---Puerto D, G(PD2) ---*/
    GPIOD->BSRR = GPIO_BSRR_BS2;//Ponemos 1 logico para asegurar que inicien apagados

    //Encendemos solo los segmentos necesario para los numeros 
        switch(numero) {
        case 0: // Para el 0 (A, B, C, D, E, F)
            GPIOA->BSRR = (GPIO_BSRR_BR12 | GPIO_BSRR_BR11);//Segmento B, F
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12 | GPIO_BSRR_BR10);//Segmento C,D, E
            break;
        case 1: // B, C
            GPIOA->BSRR = (GPIO_BSRR_BR12);//Segmento B 
            GPIOC->BSRR = (GPIO_BSRR_BR11);//Segmento C
            break;
        case 2: // A, B, D, E, G
            GPIOA->BSRR = (GPIO_BSRR_BR12);//Segmento B 
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            GPIOC->BSRR = (GPIO_BSRR_BR10 |GPIO_BSRR_BR12);//Segmento E, D
            break;
        case 3: // A, B, C, D, G
            GPIOA->BSRR = (GPIO_BSRR_BR12);//Segmento B
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento C, D
            break;
        case 4: // B, C, F, G
            GPIOA->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento F, B
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            GPIOC->BSRR = (GPIO_BSRR_BR11);//Segmento C
            break;
        case 5: // A, C, D, F, G
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOA->BSRR = (GPIO_BSRR_BR11 );//Segmento F
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento C, D
            break;
        case 6: // A, B, C, D, E, G
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOA->BSRR = (GPIO_BSRR_BR11 );//Segmento F
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12 | GPIO_BSRR_BR10);//Segmento C,D, E
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            break;
        case 7: // A, B, C
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOA->BSRR = (GPIO_BSRR_BR12);//Segmento B
            GPIOC->BSRR = (GPIO_BSRR_BR11);//Segmento C
            break;
        case 8: // A, B, C, D, E, F, G
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOA->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento F, B
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12 | GPIO_BSRR_BR10);//Segmento C,D, E
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            break;
        case 9: // A, B, C, D, F, G
            GPIOB->BSRR = (GPIO_BSRR_BR12);//Segmento A
            GPIOA->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento F, B
            GPIOC->BSRR = (GPIO_BSRR_BR11 | GPIO_BSRR_BR12);//Segmento C, D
            GPIOD->BSRR = (GPIO_BSRR_BR2);//Segmento G
            break;
    }
}

// Contador de las fotointerruptores 
void Actualizar_Contador(void) {
    // ¿Ocurrió el evento de suma?
    if (flag_sumar == 1) {
        flag_sumar = 0; // Bajamos la bandera inmediatamente

        contador++;
        if (contador > 9999) {
            contador = 0; // Reiniciar si pasa de 9999
        }
    }

    // ¿Ocurrió el evento de resta?
    if (flag_restar == 1) {
        flag_restar = 0; // Bajamos la bandera inmediatamente

        contador--;
        if (contador < 0) {
            contador = 9999; // Volver al tope si baja de cero
        }
    }
}




